-- Fresh 5-QA, 1-RC (4 questions), and 1-DILR (4 questions) package.
insert into public.daily_packages (id, date, published, quant, varc, dilr)
values ('2026-09-09', '2026-09-09', true, '[{"question":{"type":"text","value":"A product is discounted by 20% and then its discounted price is increased by 25%. The final price is:"},"options":[{"label":"A","content":{"type":"text","value":"5% lower"}},{"label":"B","content":{"type":"text","value":"5% higher"}},{"label":"C","content":{"type":"text","value":"unchanged"}},{"label":"D","content":{"type":"text","value":"20% lower"}}],"correctOption":"C","solution":{"type":"text","value":"100 becomes 80, and 80 increased by 25% becomes 100."}},{"question":{"type":"text","value":"The average of 8 numbers is 15. Replacing 22 by 30 changes the average to:"},"options":[{"label":"A","content":{"type":"text","value":"15"}},{"label":"B","content":{"type":"text","value":"16"}},{"label":"C","content":{"type":"text","value":"17"}},{"label":"D","content":{"type":"text","value":"18"}}],"correctOption":"B","solution":{"type":"text","value":"The total rises by 8, so the average rises by 1."}},{"question":{"type":"text","value":"If x + 1/x = 5, then x^2 + 1/x^2 equals:"},"options":[{"label":"A","content":{"type":"text","value":"21"}},{"label":"B","content":{"type":"text","value":"23"}},{"label":"C","content":{"type":"text","value":"25"}},{"label":"D","content":{"type":"text","value":"27"}}],"correctOption":"B","solution":{"type":"text","value":"Squaring gives x^2 + 2 + 1/x^2 = 25."}},{"question":{"type":"text","value":"A train 180 m long crosses a pole in 12 seconds. Its speed in km/h is:"},"options":[{"label":"A","content":{"type":"text","value":"36"}},{"label":"B","content":{"type":"text","value":"45"}},{"label":"C","content":{"type":"text","value":"54"}},{"label":"D","content":{"type":"text","value":"60"}}],"correctOption":"C","solution":{"type":"text","value":"180/12 = 15 m/s = 54 km/h."}},{"question":{"type":"text","value":"The smallest positive integer leaving remainder 2 on division by 5 and remainder 3 on division by 7 is:"},"options":[{"label":"A","content":{"type":"text","value":"17"}},{"label":"B","content":{"type":"text","value":"22"}},{"label":"C","content":{"type":"text","value":"27"}},{"label":"D","content":{"type":"text","value":"32"}}],"correctOption":"A","solution":{"type":"text","value":"17 leaves remainders 2 and 3 respectively."}}]'::jsonb, '{"type":"RC","title":"Reading Comprehension","passage":{"type":"text","value":"Cities are often judged by the speed with which they move people and goods. Yet speed is only one measure of urban success. A street designed solely for fast traffic may reduce travel time for drivers while making short walks unpleasant or dangerous. This can weaken the small, repeated interactions that give neighbourhoods their social life: stopping at a shop, meeting a neighbour, or allowing children to travel independently. The point is not that every street should exclude cars. Rather, planners must recognize that a road is also public space. When its design treats pedestrians, cyclists, vendors, and transit users as afterthoughts, the city may become efficient in a narrow engineering sense while becoming less useful to the people who inhabit it. Good planning therefore asks not only how quickly traffic moves, but also what kinds of everyday life the movement makes possible."},"questions":[{"question":{"type":"text","value":"The central argument is that city streets should:"},"options":[{"label":"A","content":{"type":"text","value":"be reserved for pedestrians"}},{"label":"B","content":{"type":"text","value":"be evaluated by more than vehicle speed"}},{"label":"C","content":{"type":"text","value":"remove vendors"}},{"label":"D","content":{"type":"text","value":"prioritize drivers"}}],"correctOption":"B","solution":{"type":"text","value":"The author says speed is only one measure of success."}},{"question":{"type":"text","value":"Shops, neighbours, and children illustrate:"},"options":[{"label":"A","content":{"type":"text","value":"construction costs"}},{"label":"B","content":{"type":"text","value":"social effects of street design"}},{"label":"C","content":{"type":"text","value":"why cars must be banned"}},{"label":"D","content":{"type":"text","value":"transit delays"}}],"correctOption":"B","solution":{"type":"text","value":"They are everyday social interactions affected by streets."}},{"question":{"type":"text","value":"The author would most likely agree that:"},"options":[{"label":"A","content":{"type":"text","value":"traffic engineering is sufficient"}},{"label":"B","content":{"type":"text","value":"cars have no place in cities"}},{"label":"C","content":{"type":"text","value":"transport design should consider life around a street"}},{"label":"D","content":{"type":"text","value":"fast roads always improve life"}}],"correctOption":"C","solution":{"type":"text","value":"Roads are also public spaces for many users."}},{"question":{"type":"text","value":"‘Efficient in a narrow engineering sense’ means:"},"options":[{"label":"A","content":{"type":"text","value":"successful only at moving traffic quickly"}},{"label":"B","content":{"type":"text","value":"unsafe"}},{"label":"C","content":{"type":"text","value":"too costly"}},{"label":"D","content":{"type":"text","value":"rural"}}],"correctOption":"A","solution":{"type":"text","value":"The phrase contrasts traffic speed with broader urban usefulness."}}]}'::jsonb, '{"title":"Library Seating Puzzle","set":{"type":"text","value":"Four students - Asha, Bharat, Charu and Dev - sit in a row of four seats numbered 1 to 4 from left to right. Charu sits in seat 1. Asha sits immediately to the left of Bharat. Dev does not sit next to Bharat."},"questions":[{"question":{"type":"text","value":"Who sits in seat 2?"},"options":[{"label":"A","content":{"type":"text","value":"Asha"}},{"label":"B","content":{"type":"text","value":"Bharat"}},{"label":"C","content":{"type":"text","value":"Charu"}},{"label":"D","content":{"type":"text","value":"Dev"}}],"correctOption":"D","solution":{"type":"text","value":"The valid order is Charu, Dev, Asha, Bharat."}},{"question":{"type":"text","value":"Who sits in seat 4?"},"options":[{"label":"A","content":{"type":"text","value":"Asha"}},{"label":"B","content":{"type":"text","value":"Bharat"}},{"label":"C","content":{"type":"text","value":"Charu"}},{"label":"D","content":{"type":"text","value":"Dev"}}],"correctOption":"B","solution":{"type":"text","value":"The valid order ends with Bharat."}},{"question":{"type":"text","value":"Who sits immediately to the left of Bharat?"},"options":[{"label":"A","content":{"type":"text","value":"Asha"}},{"label":"B","content":{"type":"text","value":"Charu"}},{"label":"C","content":{"type":"text","value":"Dev"}},{"label":"D","content":{"type":"text","value":"Cannot be determined"}}],"correctOption":"A","solution":{"type":"text","value":"This is directly given."}},{"question":{"type":"text","value":"Which is the correct left-to-right order?"},"options":[{"label":"A","content":{"type":"text","value":"Charu, Dev, Asha, Bharat"}},{"label":"B","content":{"type":"text","value":"Charu, Asha, Bharat, Dev"}},{"label":"C","content":{"type":"text","value":"Dev, Charu, Asha, Bharat"}},{"label":"D","content":{"type":"text","value":"Charu, Bharat, Asha, Dev"}}],"correctOption":"A","solution":{"type":"text","value":"Only this arrangement satisfies every condition."}}]}'::jsonb)
